-- Structured dimensions are opt-in. Existing literal tags are retained.
CREATE TABLE pt_dimension_settings (id INTEGER PRIMARY KEY CHECK(id=1), classes_enabled INTEGER NOT NULL DEFAULT 0 CHECK(classes_enabled IN(0,1)), locations_enabled INTEGER NOT NULL DEFAULT 0 CHECK(locations_enabled IN(0,1)), projects_enabled INTEGER NOT NULL DEFAULT 0 CHECK(projects_enabled IN(0,1)), revision TEXT NOT NULL);
INSERT INTO pt_dimension_settings(id,revision) VALUES(1,'initial');
CREATE TABLE pt_dimensions (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('class','location','project')), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), revision TEXT NOT NULL);
CREATE UNIQUE INDEX pt_dimension_name ON pt_dimensions(kind,lower(name));
CREATE TABLE pt_account_dimensions (account_id TEXT NOT NULL REFERENCES pt_accounts(id), kind TEXT NOT NULL CHECK(kind IN('class','location','project')), PRIMARY KEY(account_id,kind));
ALTER TABLE pt_invoice_lines ADD COLUMN class_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_invoice_lines ADD COLUMN location_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_invoice_lines ADD COLUMN project_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bill_lines ADD COLUMN class_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bill_lines ADD COLUMN location_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bill_lines ADD COLUMN project_name TEXT NOT NULL DEFAULT '';

CREATE TRIGGER pt_invoice_lines_dimensions_insert BEFORE INSERT ON pt_invoice_lines WHEN (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='class') AND NEW.class_name='') OR (NEW.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='class' AND name=NEW.class_name COLLATE NOCASE AND active=1)))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='location') AND NEW.location_name='') OR (NEW.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='location' AND name=NEW.location_name COLLATE NOCASE AND active=1)))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='project') AND NEW.project_name='') OR (NEW.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='project' AND name=NEW.project_name COLLATE NOCASE AND active=1)))))
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

CREATE TRIGGER pt_invoice_lines_dimensions_update BEFORE UPDATE ON pt_invoice_lines WHEN (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='class') AND NEW.class_name='') OR (NEW.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='class' AND name=NEW.class_name COLLATE NOCASE AND active=1)))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='location') AND NEW.location_name='') OR (NEW.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='location' AND name=NEW.location_name COLLATE NOCASE AND active=1)))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='project') AND NEW.project_name='') OR (NEW.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='project' AND name=NEW.project_name COLLATE NOCASE AND active=1)))))
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

