BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

CREATE TRIGGER pt_bill_lines_dimensions_update BEFORE UPDATE ON pt_bill_lines WHEN (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='class') AND NEW.class_name='') OR (NEW.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='class' AND name=NEW.class_name COLLATE NOCASE AND active=1)))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='location') AND NEW.location_name='') OR (NEW.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='location' AND name=NEW.location_name COLLATE NOCASE AND active=1)))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((EXISTS(SELECT 1 FROM pt_account_dimensions WHERE account_id=NEW.account_id AND kind='project') AND NEW.project_name='') OR (NEW.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='project' AND name=NEW.project_name COLLATE NOCASE AND active=1)))))
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

CREATE TRIGGER pt_journal_lines_dimensions_insert BEFORE INSERT ON pt_journal_lines WHEN (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='class' AND name=NEW.class_name COLLATE NOCASE AND active=1)))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='location' AND name=NEW.location_name COLLATE NOCASE AND active=1)))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='project' AND name=NEW.project_name COLLATE NOCASE AND active=1))))) AND EXISTS(SELECT 1 FROM pt_journal_entries WHERE id=NEW.entry_id AND status='draft' AND source_kind<>'reversal')
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

CREATE TRIGGER pt_journal_lines_dimensions_update BEFORE UPDATE ON pt_journal_lines WHEN (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='class' AND name=NEW.class_name COLLATE NOCASE AND active=1)))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='location' AND name=NEW.location_name COLLATE NOCASE AND active=1)))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND ((0) OR (NEW.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions WHERE kind='project' AND name=NEW.project_name COLLATE NOCASE AND active=1))))) AND EXISTS(SELECT 1 FROM pt_journal_entries WHERE id=NEW.entry_id AND status='draft' AND source_kind<>'reversal')
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

CREATE TRIGGER pt_journal_dimensions_post BEFORE UPDATE OF status ON pt_journal_entries WHEN NEW.status='posted' AND OLD.status<>'posted' AND NEW.source_kind<>'reversal' AND (((SELECT classes_enabled FROM pt_dimension_settings WHERE id=1)=1 AND EXISTS(SELECT 1 FROM pt_journal_lines l WHERE l.entry_id=NEW.id AND ((EXISTS(SELECT 1 FROM pt_account_dimensions r WHERE r.account_id=l.account_id AND r.kind='class') AND l.class_name='') OR (l.class_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions d WHERE d.kind='class' AND d.name=l.class_name COLLATE NOCASE AND d.active=1))))) OR ((SELECT locations_enabled FROM pt_dimension_settings WHERE id=1)=1 AND EXISTS(SELECT 1 FROM pt_journal_lines l WHERE l.entry_id=NEW.id AND ((EXISTS(SELECT 1 FROM pt_account_dimensions r WHERE r.account_id=l.account_id AND r.kind='location') AND l.location_name='') OR (l.location_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions d WHERE d.kind='location' AND d.name=l.location_name COLLATE NOCASE AND d.active=1))))) OR ((SELECT projects_enabled FROM pt_dimension_settings WHERE id=1)=1 AND EXISTS(SELECT 1 FROM pt_journal_lines l WHERE l.entry_id=NEW.id AND ((EXISTS(SELECT 1 FROM pt_account_dimensions r WHERE r.account_id=l.account_id AND r.kind='project') AND l.project_name='') OR (l.project_name<>'' AND NOT EXISTS(SELECT 1 FROM pt_dimensions d WHERE d.kind='project' AND d.name=l.project_name COLLATE NOCASE AND d.active=1))))))
BEGIN SELECT RAISE(ABORT,'PANTRY_DIMENSION_REQUIRED_OR_UNKNOWN'); END;

ALTER TABLE pt_bank_lines ADD COLUMN class_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bank_lines ADD COLUMN location_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bank_lines ADD COLUMN project_name TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_bank_rules ADD COLUMN dimension_conditions TEXT NOT NULL DEFAULT '{}';
ALTER TABLE pt_bank_rules ADD COLUMN dimension_actions TEXT NOT NULL DEFAULT '{}';
ALTER TABLE pt_contacts ADD COLUMN default_location TEXT NOT NULL DEFAULT '';
ALTER TABLE pt_contacts ADD COLUMN default_project TEXT NOT NULL DEFAULT '';
